Method.Implementation:
Set tSC= $$$OK $$$TRACE(" Inside InvokePostService ")
try { set jsonBodyData = pInput.Read(.len,.status) $$$TRACE(" JSON (Hie Service) : "_jsonBodyData) set jsonStrContainer=##class(Ens.StringContainer).%New() set jsonStrContainer.StringValue= jsonBodyData
set pResponse = jsonStrContainer
$$$TRACE(..TargetConfigNames)
For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W") $$$TRACE("tOneTarget " _ tOneTarget) do ..SendRequestAsync(tOneTarget,pResponse) }
}catch e { $$$TRACE(" Unknown Exception: " _ e) set errTxt = $System.Status.GetErrorText("Unknown Exception while receiving post request from Hie Patient Service "_e) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt) set tSC = $$$OK
} quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
